                    const e1: u32 = k.a[2] +% @as(u32, 8);
                    k.wb(e1, v);
                    k.logic(u8, v);
                }
                // $05858  adda.l #$56, a2
                {
                    k.cy +%= 12;
                    k.a[2] +%= @as(u32, 0x56);
                }
                // $0585e  dbra d0, $15834
                {
                    k.cy +%= 14;
                    const w = k.dv(u16, 0) -% 1;
                    k.setD(u16, 0, w);
                    if (w != 0xFFFF) { if (k.cy >= k.limit) return 0x15834; continue :sw 0x15834; }
                }
                // $05862  move.b #$1, $1057c.l
                {
                    k.cy +%= 20;
                    const v = @as(u8, 0x1);
                    const e1: u32 = 0x1057c;
                    k.wb(e1, v);
                    k.logic(u8, v);
                }
                // $0586a  lea.l $1903c.l, a1
                {
                    k.cy +%= 12;
                    k.a[1] = 0x1903c;
                }
                // $05870  bsr.w $18e48
                {
                    k.cy +%= 32;
                    k.push32(0x15874);
                    return 0x18e48;
                }
            },
            0x15874 => {
                // $05874  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            else => return k.bad(pc),
        }
    }

};

